INSERT [dbo].[blog_posts] ([id], [title], [slug], [content], [thumbnail_url], [author_id], [status], [published_at], [created_at], [updated_at], [category_id]) VALUES (1, N'5 Dấu hiệu cảnh báo bệnh tăng nhãn áp bạn không nên bỏ qua', N'5-dau-hieu-canh-bao-tang-nhan-ap', N'Tăng nhãn áp thường được gọi là "kẻ trộm thị giác" vì tiến triển âm thầm. Chú ý 5 dấu hiệu: (1) Mờ mắt thoáng qua, (2) Đau đầu phía trán, (3) Nhìn thấy quầng sáng quanh đèn, (4) Thu hẹp thị trường ngoại vi, (5) Buồn nôn kèm đau mắt. Khám nhãn áp định kỳ là cách phát hiện sớm hiệu quả nhất.', NULL, 3, N'PUBLISHED', CAST(N'2026-06-20T04:05:34.6000000' AS DateTime2), CAST(N'2026-06-18T04:05:34.6000000' AS DateTime2), NULL, NULL)
INSERT [dbo].[blog_posts] ([id], [title], [slug], [content], [thumbnail_url], [author_id], [status], [published_at], [created_at], [updated_at], [category_id]) VALUES (2, N'Kính áp tròng: Những điều cần biết để bảo vệ mắt', N'kinh-ap-trong-nhung-dieu-can-biet', N'Kính áp tròng tiện lợi nhưng sử dụng sai cách rất nguy hiểm. Nguyên tắc vàng: (1) Rửa tay trước khi đeo/tháo, (2) Không đeo khi ngủ, (3) Không dùng nước máy thay nước muối rửa kính, (4) Thay kính đúng chu kỳ, (5) Tháo ngay khi mắt đỏ hoặc đau.', NULL, 4, N'PUBLISHED', CAST(N'2026-06-25T04:05:34.6000000' AS DateTime2), CAST(N'2026-06-23T04:05:34.6000000' AS DateTime2), NULL, NULL)
INSERT [dbo].[blog_posts] ([id], [title], [slug], [content], [thumbnail_url], [author_id], [status], [published_at], [created_at], [updated_at], [category_id]) VALUES (3, N'Phẫu thuật Phaco điều trị đục thể thủy tinh — Quy trình và kết quả', N'phau-thuat-phaco-duc-the-thuy-tinh', N'Đục thể thủy tinh là nguyên nhân hàng đầu gây mù lòa có thể phòng ngừa. Phẫu thuật Phaco chỉ mất 15-20 phút, không cần nằm viện, bệnh nhân phục hồi thị lực trong 24-48 giờ. Bài viết này giải thích chi tiết quy trình và những điều cần chuẩn bị.', NULL, 5, N'DRAFT', NULL, CAST(N'2026-06-29T04:05:34.6000000' AS DateTime2), NULL, NULL)
